ON target.Partner_Transaction_Code = source.Partner_Transaction_Code
WHEN MATCHED THEN
    UPDATE SET target.Transaction_Status = source.Transaction_Status, target.Receipt_URL = source.Receipt_URL
WHEN NOT MATCHED THEN
    INSERT (Plan_ID, User_ID, Gateway_Provider, Partner_Transaction_Code, Amount_VND, Transaction_Status, Signature_Hash, Created_At, Completed_At, Receipt_URL, Starts_At, Ends_At)
    VALUES (source.Plan_ID, source.User_ID, source.Gateway_Provider, source.Partner_Transaction_Code, source.Amount_VND, source.Transaction_Status, source.Signature_Hash, source.Created_At, source.Completed_At, source.Receipt_URL, source.Starts_At, source.Ends_At);
