MERGE INTO dbo.Recipes AS target
USING (
    VALUES

        (101, 2, 1, 1, N'Canh nấm đậu phụ rong biển', N'Món canh thanh đạm bổ dưỡng mát lành giải nhiệt cơ thể với đậu hũ non và nấm rơm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Canh nấm đậu phụ rong biển.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Canh nấm đậu phụ rong biển ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 310.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252680/veggielife/recipes/canh_nam_dau_phu.jpg', 'APPROVED_ACTIVE', 200, 'USER', DATEADD(DAY, -3, SYSDATETIME())),
        (102, 3, 1, 4, N'Súp ngô ngọt kem tươi dinh dưỡng', N'Súp thơm mùi bơ sữa và ngọt thanh tự nhiên từ bắp ngọt tươi mát.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Súp ngô ngọt kem tươi dinh dưỡng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Súp ngô ngọt kem tươi dinh dưỡng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 280.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252685/veggielife/recipes/sup_ngo_ngot.jpg', 'APPROVED_ACTIVE', 215, 'USER', DATEADD(DAY, -4, SYSDATETIME())),
        (103, 4, 1, 1, N'Canh chua chay Nam Bộ thơm lừng', N'Canh chua ngọt đậm đà vị dứa, đậu bắp, bạc hà và đậu hũ chiên béo bùi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Canh chua chay Nam Bộ thơm lừng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Canh chua chay Nam Bộ thơm lừng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 260.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252703/veggielife/recipes/canh_chua_chay.jpg', 'APPROVED_ACTIVE', 230, 'USER', DATEADD(DAY, -5, SYSDATETIME())),
        (104, 5, 1, 1, N'Súp bí đỏ cốt dừa sánh mịn', N'Súp bí đỏ béo ngậy ngọt tự nhiên từ nước cốt dừa hữu cơ.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Súp bí đỏ cốt dừa sánh mịn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Súp bí đỏ cốt dừa sánh mịn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 30, 2, 320.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252712/veggielife/recipes/sup_bi_do_cot_dua.jpg', 'APPROVED_ACTIVE', 245, 'USER', DATEADD(DAY, -6, SYSDATETIME())),
        (105, 6, 1, 5, N'Canh khổ qua nhồi đậu hũ nấm mèo', N'Vị đắng thanh của khổ qua hòa quyện nhân đậu hũ nấm giòn ngọt thanh nhiệt.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Canh khổ qua nhồi đậu hũ nấm mèo.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Canh khổ qua nhồi đậu hũ nấm mèo ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 35, 4, 220.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 260, 'USER', DATEADD(DAY, -7, SYSDATETIME())),
        (106, 7, 1, 6, N'Súp nấm tuyết hạt sen táo đỏ', N'Món súp bồi bổ dưỡng nhan nhuận phế tuyệt hảo cho sức khỏe.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Súp nấm tuyết hạt sen táo đỏ.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Súp nấm tuyết hạt sen táo đỏ ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 40, 3, 250.0, 'HARD', 1, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 275, 'USER', DATEADD(DAY, -8, SYSDATETIME())),
        (107, 8, 1, 6, N'Canh củ sen hầm đậu đỏ bổ máu', N'Nước canh ngọt đậm đà từ củ sen giòn sần sật và đậu đỏ bùi bùi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Canh củ sen hầm đậu đỏ bổ máu.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Canh củ sen hầm đậu đỏ bổ máu ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 15, 2, 290.0, 'EASY', 1, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 290, 'USER', DATEADD(DAY, -9, SYSDATETIME())),
        (108, 9, 2, 1, N'Nấm kho tiêu hạt sen đậm đà', N'Nấm kho sánh quyện đậm đà đưa cơm chuẩn vị chay gia đình Việt Nam.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm kho tiêu hạt sen đậm đà.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm kho tiêu hạt sen đậm đà ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 240.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252682/veggielife/recipes/nam_kho_tieu.jpg', 'APPROVED_ACTIVE', 305, 'USER', DATEADD(DAY, -10, SYSDATETIME())),
        (109, 10, 2, 1, N'Đậu hũ sốt cà chua nấm rơm', N'Món ăn dân dã quốc dân với đậu hũ mềm ngấm sốt cà chua đỏ mọng chua ngọt.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu hũ sốt cà chua nấm rơm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu hũ sốt cà chua nấm rơm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 260.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252764/veggielife/recipes/dau_hu_sot_ca_chua.jpg', 'APPROVED_ACTIVE', 320, 'USER', DATEADD(DAY, -11, SYSDATETIME())),
        (110, 11, 2, 5, N'Mít non kho tiêu xanh đậm vị quê', N'Thớ mít non dai giòn thấm đẫm tiêu sọ xanh cay nồng và nước tương nguyên chất.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Mít non kho tiêu xanh đậm vị quê.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Mít non kho tiêu xanh đậm vị quê ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 230.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252705/veggielife/recipes/mit_non_kho_tieu.jpg', 'APPROVED_ACTIVE', 335, 'USER', DATEADD(DAY, -12, SYSDATETIME())),
        (111, 12, 2, 1, N'Đậu hũ kho sả ớt cay nồng bắt cơm', N'Miếng đậu hũ chiên vàng ươm thơm lừng mùi sả phi vàng cay nhẹ.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu hũ kho sả ớt cay nồng bắt cơm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu hũ kho sả ớt cay nồng bắt cơm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 270.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 350, 'USER', DATEADD(DAY, -13, SYSDATETIME())),
        (112, 13, 2, 1, N'Măng tươi kho nước dừa xiêm', N'Măng giòn ngọt tự nhiên kho mềm rục trong nước dừa tươi ngọt lịm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Măng tươi kho nước dừa xiêm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Măng tươi kho nước dừa xiêm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 210.0, 'HARD', 1, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 365, 'USER', DATEADD(DAY, -14, SYSDATETIME())),
        (113, 14, 2, 1, N'Sườn non chay rim mặn ngọt mè rang', N'Sườn chay giòn dai ngấm nước sốt caramel mặn ngọt và hạt mè rang béo ngậy.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Sườn non chay rim mặn ngọt mè rang.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Sườn non chay rim mặn ngọt mè rang ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 350.0, 'EASY', 1, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 380, 'USER', DATEADD(DAY, -15, SYSDATETIME())),
        (114, 15, 2, 6, N'Nấm đùi gà kho gừng ấm nồng', N'Nấm đùi gà ngọt bùi hòa quyện vị cay ấm của gừng tươi thái sợi mỏng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm đùi gà kho gừng ấm nồng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm đùi gà kho gừng ấm nồng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 230.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 395, 'USER', DATEADD(DAY, -16, SYSDATETIME())),
        (115, 16, 3, 1, N'Mì xào nấm rau củ giòn ngọt', N'Món mì xào giòn thơm kèm nấm kim châm tươi và cải ngọt thanh mát.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Mì xào nấm rau củ giòn ngọt.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Mì xào nấm rau củ giòn ngọt ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 350.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252684/veggielife/recipes/mi_xao_nam_rau_cu.jpg', 'APPROVED_ACTIVE', 410, 'USER', DATEADD(DAY, -17, SYSDATETIME())),
        (116, 17, 3, 1, N'Nấm đùi gà áp chảo sốt tiêu đen', N'Nấm dai ngọt tự nhiên như thịt bò nướng áp chảo với sốt tiêu cay nồng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm đùi gà áp chảo sốt tiêu đen.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm đùi gà áp chảo sốt tiêu đen ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 30, 2, 290.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252702/veggielife/recipes/nam_dui_ga_ap_chao.jpg', 'APPROVED_ACTIVE', 425, 'USER', DATEADD(DAY, -18, SYSDATETIME())),
        (117, 18, 3, 1, N'Đậu cove xào nấm đông cô dầu hào', N'Đậu xanh giòn sần sật ngấm sốt dầu hào chay đậm đà bóng mượt.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu cove xào nấm đông cô dầu hào.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu cove xào nấm đông cô dầu hào ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 35, 4, 210.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252713/veggielife/recipes/dau_cove_xao_nam.jpg', 'APPROVED_ACTIVE', 440, 'USER', DATEADD(DAY, -19, SYSDATETIME())),
        (118, 19, 3, 1, N'Nui xào rau củ sốt tương chay', N'Nui mềm dai xào cùng bông cải xanh giòn và nấm rơm thơm lừng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nui xào rau củ sốt tương chay.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nui xào rau củ sốt tương chay ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 40, 3, 340.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252768/veggielife/recipes/nui_xao_rau_cu.jpg', 'APPROVED_ACTIVE', 455, 'USER', DATEADD(DAY, -20, SYSDATETIME())),
        (119, 20, 3, 5, N'Miến xào rau củ thập cẩm chay', N'Sợi miến dong trong suốt tơi mềm không dính, xào cùng nấm mèo và cà rốt.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Miến xào rau củ thập cẩm chay.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Miến xào rau củ thập cẩm chay ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 15, 2, 320.0, 'EASY', 1, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 470, 'USER', DATEADD(DAY, -21, SYSDATETIME())),
        (120, 21, 3, 1, N'Bông cải xanh xào nấm bào ngư', N'Bông cải xanh giòn mọng nước xào nấm bào ngư xám bổ sung chất xơ và đạm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bông cải xanh xào nấm bào ngư.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bông cải xanh xào nấm bào ngư ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 190.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 485, 'USER', DATEADD(DAY, -22, SYSDATETIME())),
        (121, 22, 3, 1, N'Nấm linh chi xào ớt chuông ba màu', N'Màu sắc rực rỡ từ ớt chuông đỏ vàng xanh hòa quyện nấm linh chi nâu béo.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm linh chi xào ớt chuông ba màu.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm linh chi xào ớt chuông ba màu ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 220.0, 'HARD', 1, 'https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 500, 'USER', DATEADD(DAY, -23, SYSDATETIME())),
        (122, 23, 4, 1, N'Chả giò chay khoai môn giòn rụm', N'Chả giò chiên vàng ươm với nhân bùi béo từ khoai môn và nấm mèo thái sợi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chả giò chay khoai môn giòn rụm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chả giò chay khoai môn giòn rụm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 320.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252688/veggielife/recipes/cha_gio_chay.jpg', 'APPROVED_ACTIVE', 515, 'USER', DATEADD(DAY, -24, SYSDATETIME())),
        (123, 24, 4, 2, N'Đậu hũ non chiên xù sốt mè rang', N'Vỏ ngoài giòn rụm bên trong mềm mịn tan ngay đầu lưỡi, phủ mè rang thơm phức.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu hũ non chiên xù sốt mè rang.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu hũ non chiên xù sốt mè rang ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 310.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252699/veggielife/recipes/dau_hu_non_chien_xu.jpg', 'APPROVED_ACTIVE', 530, 'USER', DATEADD(DAY, -25, SYSDATETIME())),
        (124, 25, 4, 1, N'Bánh xèo chay nấm kim châm giòn', N'Vỏ bánh giòn tan màu vàng nghệ, nhân nấm kim châm ngọt giòn và giá đỗ tươi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh xèo chay nấm kim châm giòn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh xèo chay nấm kim châm giòn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 360.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252708/veggielife/recipes/banh_xeo_chay.jpg', 'APPROVED_ACTIVE', 545, 'USER', DATEADD(DAY, -26, SYSDATETIME())),
        (125, 26, 4, 1, N'Cà tím nướng mỡ hành sốt tương tỏi', N'Cà tím nướng than thơm phức mềm ngọt ngấm sốt tương tỏi ớt hấp dẫn.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cà tím nướng mỡ hành sốt tương tỏi.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cà tím nướng mỡ hành sốt tương tỏi ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 230.0, 'EASY', 1, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 560, 'USER', DATEADD(DAY, -2, SYSDATETIME())),
        (126, 2, 4, 1, N'Nấm bào ngư chiên giòn chấm tương ớt', N'Từng tai nấm tẩm bột chiên xù vàng ươm giòn tan như snack lành mạnh.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm bào ngư chiên giòn chấm tương ớt.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm bào ngư chiên giòn chấm tương ớt ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 280.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 575, 'USER', DATEADD(DAY, -3, SYSDATETIME())),
        (127, 3, 4, 1, N'Chả cá lát chay chiên thì là nghệ', N'Thì là thơm lừng kết hợp nghệ vàng tạo nên đĩa chả chay hương vị Chả cá Lã Vọng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chả cá lát chay chiên thì là nghệ.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chả cá lát chay chiên thì là nghệ ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 290.0, 'HARD', 1, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 590, 'USER', DATEADD(DAY, -4, SYSDATETIME())),
        (128, 4, 4, 1, N'Bí ngòi xanh cuộn nấm đùi gà nướng', N'Lát bí ngòi xanh mỏng cuộn nấm đùi gà nướng chín tới ngọt thanh thơm mùi khói.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bí ngòi xanh cuộn nấm đùi gà nướng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bí ngòi xanh cuộn nấm đùi gà nướng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 30, 2, 240.0, 'EASY', 1, 'https://images.unsplash.com/photo-1505253758473-96b301b5c81d?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 605, 'USER', DATEADD(DAY, -5, SYSDATETIME())),
        (129, 5, 5, 1, N'Rau củ luộc chấm kho quẹt chay', N'Rau củ tươi Đà Lạt luộc xanh mướt chấm nồi kho quẹt nấm hương tiêu hạt cay nồng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Rau củ luộc chấm kho quẹt chay.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Rau củ luộc chấm kho quẹt chay ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 35, 4, 220.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252709/veggielife/recipes/rau_cu_luoc_kho_quet.jpg', 'APPROVED_ACTIVE', 620, 'USER', DATEADD(DAY, -6, SYSDATETIME())),
        (130, 6, 5, 1, N'Đậu bắp luộc chấm chao ớt Sa Đéc', N'Đậu bắp luộc xanh non ngọt nước chấm chao môn béo ngậy cay cay bắt vị.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu bắp luộc chấm chao ớt Sa Đéc.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu bắp luộc chấm chao ớt Sa Đéc ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 40, 3, 160.0, 'HARD', 1, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 635, 'USER', DATEADD(DAY, -7, SYSDATETIME())),
        (131, 7, 5, 1, N'Đậu hũ non sốt nấm bào ngư dầu mè', N'Đậu hũ non hấp mềm mượt rưới nước sốt nấm bào ngư sóng sánh thơm nức mũi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Đậu hũ non sốt nấm bào ngư dầu mè.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Đậu hũ non sốt nấm bào ngư dầu mè ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 15, 2, 230.0, 'EASY', 1, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 650, 'USER', DATEADD(DAY, -8, SYSDATETIME())),
        (132, 8, 5, 6, N'Cơm gạo lứt hạt sen bọc lá sen hấp', N'Hương sen thanh tao thấm sâu vào từng hạt cơm gạo lứt dẻo bùi bổ dưỡng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cơm gạo lứt hạt sen bọc lá sen hấp.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cơm gạo lứt hạt sen bọc lá sen hấp ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 340.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 665, 'USER', DATEADD(DAY, -9, SYSDATETIME())),
        (133, 9, 5, 1, N'Bánh bao chay nhân nấm miến mộc nhĩ', N'Vỏ bánh trắng xốp thơm mùi sữa hạt, nhân nấm miến mộc nhĩ đậm đà vừa miệng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh bao chay nhân nấm miến mộc nhĩ.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh bao chay nhân nấm miến mộc nhĩ ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 280.0, 'HARD', 1, 'https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 680, 'USER', DATEADD(DAY, -10, SYSDATETIME())),
        (134, 10, 5, 1, N'Bắp ngọt hấp nước dừa bùi béo', N'Từng hạt bắp Mỹ căng mọng ngọt lịm ngấm vị béo bùi của nước dừa tươi nguyên chất.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bắp ngọt hấp nước dừa bùi béo.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bắp ngọt hấp nước dừa bùi béo ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 190.0, 'EASY', 1, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 695, 'USER', DATEADD(DAY, -11, SYSDATETIME())),
        (135, 11, 5, 6, N'Nấm đông cô hấp xì dầu gừng sợi', N'Tai nấm tươi dày dặn hấp cùng gừng non giữ trọn vị ngọt umami tự nhiên.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nấm đông cô hấp xì dầu gừng sợi.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nấm đông cô hấp xì dầu gừng sợi ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 210.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 710, 'USER', DATEADD(DAY, -12, SYSDATETIME())),
        (136, 12, 6, 1, N'Gỏi cuốn ngũ sắc chấm tương đậu', N'Gỏi cuốn thanh mát nhiều rau xanh, bún tươi và đậu hũ chiên giòn rụm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Gỏi cuốn ngũ sắc chấm tương đậu.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Gỏi cuốn ngũ sắc chấm tương đậu ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 220.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252687/veggielife/recipes/goi_cuon_chay.jpg', 'APPROVED_ACTIVE', 725, 'USER', DATEADD(DAY, -13, SYSDATETIME())),
        (137, 13, 6, 1, N'Gỏi ngó sen tôm chay nấm tuyết', N'Ngó sen giòn trắng muốt bóp gỏi chua ngọt cùng nấm tuyết và đậu phộng rang.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Gỏi ngó sen tôm chay nấm tuyết.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Gỏi ngó sen tôm chay nấm tuyết ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 240.0, 'EASY', 1, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 740, 'USER', DATEADD(DAY, -14, SYSDATETIME())),
        (138, 14, 6, 5, N'Gỏi hoa chuối bóp gỏi đậu phộng', N'Hoa chuối thái mỏng ngâm chanh giòn ngọt không chát, trộn rau răm và ớt sợi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Gỏi hoa chuối bóp gỏi đậu phộng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Gỏi hoa chuối bóp gỏi đậu phộng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 230.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 755, 'USER', DATEADD(DAY, -15, SYSDATETIME())),
        (139, 15, 6, 1, N'Bánh ướt cuốn rau mầm chả chay', N'Bánh ướt tráng mỏng cuốn rau mầm tươi non và lát chả lụa chay chấm tương béo.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh ướt cuốn rau mầm chả chay.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh ướt cuốn rau mầm chả chay ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 270.0, 'HARD', 1, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 770, 'USER', DATEADD(DAY, -16, SYSDATETIME())),
        (140, 16, 6, 1, N'Gỏi xoài xanh tôm chay giòn', N'Vị chua thanh giòn tan của xoài xanh kết hợp đậu phộng rang và sườn chay xé sợi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Gỏi xoài xanh tôm chay giòn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Gỏi xoài xanh tôm chay giòn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 30, 2, 210.0, 'EASY', 1, 'https://images.unsplash.com/photo-1505253758473-96b301b5c81d?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 785, 'USER', DATEADD(DAY, -17, SYSDATETIME())),
        (141, 17, 6, 1, N'Nộm đu đủ bò khô chay đậu phộng', N'Sợi đu đủ giòn sần sật trộn nước mắm chua ngọt, bên trên phủ bò khô chay thơm cay.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Nộm đu đủ bò khô chay đậu phộng.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Nộm đu đủ bò khô chay đậu phộng ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 35, 4, 220.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 800, 'USER', DATEADD(DAY, -18, SYSDATETIME())),
        (142, 18, 6, 1, N'Phở cuốn rau mầm đậu hũ chiên giòn', N'Bánh phở vuông mềm dẻo cuộn đậu hũ chiên nóng hổi và xà lách chấm tương bơ đậu phộng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Phở cuốn rau mầm đậu hũ chiên giòn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Phở cuốn rau mầm đậu hũ chiên giòn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 40, 3, 260.0, 'HARD', 1, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 815, 'USER', DATEADD(DAY, -19, SYSDATETIME())),
        (143, 19, 7, 1, N'Bún bò Huế chay nước dùng củ quả', N'Nước dùng hầm từ mía, củ cải ngọt đậm đà hòa quyện sả ớt cay nồng chuẩn vị cố đô.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bún bò Huế chay nước dùng củ quả.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bún bò Huế chay nước dùng củ quả ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 15, 2, 380.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252690/veggielife/recipes/bun_bo_hue_chay.jpg', 'APPROVED_ACTIVE', 830, 'USER', DATEADD(DAY, -20, SYSDATETIME())),
        (144, 20, 7, 5, N'Phở chay truyền thống nấm hương quế hồi', N'Hương vị phở Hà Nội chay thanh tịnh, không hành tỏi ngũ vị tân theo trường phái Phật giáo.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Phở chay truyền thống nấm hương quế hồi.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Phở chay truyền thống nấm hương quế hồi ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 360.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252691/veggielife/recipes/pho_chay.jpg', 'APPROVED_ACTIVE', 845, 'USER', DATEADD(DAY, -21, SYSDATETIME())),
        (145, 21, 7, 1, N'Bún chả giò chay rau sống thanh mát', N'Bún tươi ăn kèm chả giò giòn tan, dưa leo băm, đồ chua và nước mắm chay chua ngọt thanh tao.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bún chả giò chay rau sống thanh mát.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bún chả giò chay rau sống thanh mát ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 370.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252700/veggielife/recipes/bun_cha_gio_chay.jpg', 'APPROVED_ACTIVE', 860, 'USER', DATEADD(DAY, -22, SYSDATETIME())),
        (146, 22, 7, 1, N'Hủ tiếu Nam Vang chay nước lèo mía lê', N'Nước súp trong ngọt thanh từ lê và mía lau, ăn kèm hủ tiếu dai và hoành thánh chiên.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Hủ tiếu Nam Vang chay nước lèo mía lê.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Hủ tiếu Nam Vang chay nước lèo mía lê ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 350.0, 'EASY', 1, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 875, 'USER', DATEADD(DAY, -23, SYSDATETIME())),
        (147, 23, 7, 1, N'Bánh canh nấm rơm giò chay đậm đà', N'Sợi bánh canh bột lọc dai dẻo chan nước dùng nấm sền sệt rắc tiêu đen thơm lừng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh canh nấm rơm giò chay đậm đà.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh canh nấm rơm giò chay đậm đà ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 360.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 890, 'USER', DATEADD(DAY, -24, SYSDATETIME())),
        (148, 24, 7, 1, N'Bún riêu chay cua đồng từ đậu hũ non', N'Riêu cua chay làm từ đậu hũ non xay nhuyễn và nấm rơm béo ngậy thơm mùi giấm bỗng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bún riêu chay cua đồng từ đậu hũ non.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bún riêu chay cua đồng từ đậu hũ non ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 370.0, 'HARD', 1, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 905, 'USER', DATEADD(DAY, -25, SYSDATETIME())),
        (149, 25, 7, 1, N'Bún măng nấm chay nước dùng ngọt thanh', N'Măng tươi giòn ngọt nấu cùng nấm hương và nấm rơm tạo nên bát bún ấm áp bổ dưỡng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bún măng nấm chay nước dùng ngọt thanh.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bún măng nấm chay nước dùng ngọt thanh ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 340.0, 'EASY', 1, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 920, 'USER', DATEADD(DAY, -26, SYSDATETIME())),
        (150, 26, 8, 1, N'Cơm chiên trái thơm hạt sen', N'Cơm chiên hạt tơi xốp, ngọt dịu vị dứa tươi và bùi bùi từ hạt sen Đồng Tháp.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cơm chiên trái thơm hạt sen.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cơm chiên trái thơm hạt sen ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 390.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252695/veggielife/recipes/com_chien_trai_thom.jpg', 'APPROVED_ACTIVE', 935, 'USER', DATEADD(DAY, -2, SYSDATETIME())),
        (151, 2, 8, 1, N'Cơm niêu nấm rơm kho tộ cháy giòn', N'Cơm nấu niêu đất lớp cháy giòn rụm rưới nước sốt nấm rơm kho tộ thơm nức mũi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cơm niêu nấm rơm kho tộ cháy giòn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cơm niêu nấm rơm kho tộ cháy giòn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 420.0, 'HARD', 1, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 950, 'USER', DATEADD(DAY, -3, SYSDATETIME())),
