        (168, 19, 10, 1, N'Cháo bí đỏ đậu gà giàu đạm', N'Đậu gà bùi bùi giàu protein thực vật hầm nhừ cùng bí đỏ ngọt lịm bổ não.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cháo bí đỏ đậu gà giàu đạm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cháo bí đỏ đậu gà giàu đạm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 310.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1205, 'USER', DATEADD(DAY, -20, SYSDATETIME())),
        (169, 20, 10, 6, N'Cháo gạo lứt đậu đen giải độc gan', N'Gạo lứt đỏ huyết rồng nấu cùng đậu đen xanh lòng thanh lọc gan thận tuyệt hảo.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cháo gạo lứt đậu đen giải độc gan.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cháo gạo lứt đậu đen giải độc gan ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 260.0, 'HARD', 1, 'https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1220, 'USER', DATEADD(DAY, -21, SYSDATETIME())),
        (170, 21, 10, 1, N'Cháo nấm mối khoai môn dẻo thơm', N'Đặc sản nấm mối ngọt ngào tự nhiên ninh cùng khoai môn sáp dẻo quánh thơm lừng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Cháo nấm mối khoai môn dẻo thơm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Cháo nấm mối khoai môn dẻo thơm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 300.0, 'EASY', 1, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1235, 'USER', DATEADD(DAY, -22, SYSDATETIME())),
        (171, 22, 11, 1, N'Bánh mì chay pate nấm chả lụa', N'Bánh mì giòn rụm phết pate nấm béo ngậy, kẹp chả lụa chay, dưa leo và ngò rí tươi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh mì chay pate nấm chả lụa.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh mì chay pate nấm chả lụa ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 380.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252710/veggielife/recipes/banh_mi_chay.jpg', 'APPROVED_ACTIVE', 1250, 'USER', DATEADD(DAY, -23, SYSDATETIME())),
        (172, 23, 11, 1, N'Bánh ít trần chay nhân đậu xanh', N'Vỏ bánh nếp dẻo thơm nhân đậu xanh tán nhuyễn xào nấm mèo rắc hành boa rô phi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh ít trần chay nhân đậu xanh.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh ít trần chay nhân đậu xanh ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 290.0, 'HARD', 1, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1265, 'USER', DATEADD(DAY, -24, SYSDATETIME())),
        (173, 24, 11, 1, N'Bánh chuối nướng cốt dừa yến mạch', N'Bánh nướng vàng thơm nức mùi chuối sứ chín muồi và nước cốt dừa béo ngọt lịm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh chuối nướng cốt dừa yến mạch.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh chuối nướng cốt dừa yến mạch ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 320.0, 'EASY', 1, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1280, 'USER', DATEADD(DAY, -25, SYSDATETIME())),
        (174, 25, 11, 1, N'Bánh củ cải hấp nấm đông cô giòn', N'Bánh củ cải trắng hấp dai mềm sần sật nấm hương chấm xì dầu tỏi ớt tuyệt ngon.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh củ cải hấp nấm đông cô giòn.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh củ cải hấp nấm đông cô giòn ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 260.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1295, 'USER', DATEADD(DAY, -26, SYSDATETIME())),
        (175, 26, 11, 1, N'Khoai lang kén chiên giòn mè đen', N'Khoai lang mật vàng ươm nghiền nhuyễn nắn hình con kén lăn mè đen chiên giòn rụm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Khoai lang kén chiên giòn mè đen.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Khoai lang kén chiên giòn mè đen ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 25, 3, 310.0, 'HARD', 1, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1310, 'USER', DATEADD(DAY, -2, SYSDATETIME())),
        (176, 2, 11, 1, N'Bánh bèo chén chay sốt đậu xanh nấm', N'Chén bánh bèo mướt mát rưới sốt đậu xanh béo bùi và vụn bánh mì chiên giòn rụm.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh bèo chén chay sốt đậu xanh nấm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh bèo chén chay sốt đậu xanh nấm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 30, 2, 270.0, 'EASY', 1, 'https://images.unsplash.com/photo-1505253758473-96b301b5c81d?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1325, 'USER', DATEADD(DAY, -3, SYSDATETIME())),
        (177, 3, 11, 1, N'Bánh giò chay nhân nấm mộc nhĩ bột mềm', N'Gói trong lá chuối xanh thơm lừng, bột bánh mềm mượt nhân nấm mộc nhĩ tiêu đen.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Bánh giò chay nhân nấm mộc nhĩ bột mềm.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Bánh giò chay nhân nấm mộc nhĩ bột mềm ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 35, 4, 280.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1340, 'USER', DATEADD(DAY, -4, SYSDATETIME())),
        (178, 4, 12, 1, N'Chè hạt sen long nhãn thanh mát', N'Món tráng miệng cung đình Huế giải nhiệt bổ tâm an thần ngủ ngon giấc.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè hạt sen long nhãn thanh mát.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè hạt sen long nhãn thanh mát ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 40, 3, 260.0, 'HARD', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252714/veggielife/recipes/che_hat_sen_long_nhan.jpg', 'APPROVED_ACTIVE', 1355, 'USER', DATEADD(DAY, -5, SYSDATETIME())),
        (179, 5, 12, 1, N'Chè dưỡng nhan tuyết yến thảo mộc', N'Chè thanh mát quy tụ tuyết yến, kỷ tử, táo đỏ và hạt sen bồi dưỡng làn da tươi trẻ.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè dưỡng nhan tuyết yến thảo mộc.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè dưỡng nhan tuyết yến thảo mộc ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 15, 2, 240.0, 'EASY', 1, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1370, 'USER', DATEADD(DAY, -6, SYSDATETIME())),
        (180, 6, 12, 1, N'Chè bưởi An Giang giòn ngọt cốt dừa', N'Cùi bưởi giòn sần sật không chút đắng chìm trong chè đậu xanh sánh dẻo thơm nước dừa.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè bưởi An Giang giòn ngọt cốt dừa.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè bưởi An Giang giòn ngọt cốt dừa ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 20, 4, 290.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1385, 'USER', DATEADD(DAY, -7, SYSDATETIME())),
        (181, 7, 12, 1, N'Chè đậu đen nước cốt dừa bột lọc', N'Hạt đậu đen bùi mềm ngọt lịm ăn kèm viên bột lọc dai giòn và dừa nạo sợi tươi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè đậu đen nước cốt dừa bột lọc.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 25 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè đậu đen nước cốt dừa bột lọc ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 25, 3, 280.0, 'HARD', 1, 'https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1400, 'USER', DATEADD(DAY, -8, SYSDATETIME())),
        (182, 8, 12, 4, N'Chè khúc bạch hạnh nhân cốt dừa', N'Từng viên khúc bạch mềm tan thơm ngậy hạnh nhân lát hòa nước đường phèn dịu ngọt.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè khúc bạch hạnh nhân cốt dừa.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 30 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè khúc bạch hạnh nhân cốt dừa ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 30, 2, 310.0, 'EASY', 1, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1415, 'USER', DATEADD(DAY, -9, SYSDATETIME())),
        (183, 9, 12, 1, N'Tàu hũ trân châu đường đen thanh mát', N'Tàu hũ non mềm mượt như mây chan nước đường thốt nốt thơm mùi gừng non ấm nồng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Tàu hũ trân châu đường đen thanh mát.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 35 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Tàu hũ trân châu đường đen thanh mát ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 20, 35, 4, 250.0, 'MEDIUM', 1, 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1430, 'USER', DATEADD(DAY, -10, SYSDATETIME())),
        (184, 10, 12, 1, N'Chè thưng ngũ sắc khoai lang đậu xanh', N'Bát chè Nam Bộ trù phú ngập tràn khoai lang, đậu xanh, nấm mèo và đậu phộng béo bùi.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Chè thưng ngũ sắc khoai lang đậu xanh.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 40 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Chè thưng ngũ sắc khoai lang đậu xanh ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 25, 40, 3, 320.0, 'HARD', 1, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'APPROVED_ACTIVE', 1445, 'USER', DATEADD(DAY, -11, SYSDATETIME())),
        (185, 11, 13, 1, N'Sữa hạt macca óc chó nguyên chất', N'Thức uống béo bùi giàu axit béo Omega-3 từ quả óc chó và hạt mắc ca cao cấp.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Sữa hạt macca óc chó nguyên chất.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 15 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Sữa hạt macca óc chó nguyên chất ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 10, 15, 2, 210.0, 'EASY', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252715/veggielife/recipes/sua_hat_macca_oc_cho.jpg', 'APPROVED_ACTIVE', 1460, 'USER', DATEADD(DAY, -12, SYSDATETIME())),
        (186, 12, 13, 1, N'Sinh tố bơ chuối cải kale giàu xơ', N'Bữa phụ xanh lành mạnh giúp thải độc cơ thể và duy trì vóc dáng thon gọn tràn đầy năng lượng.', N'["Bước 1: Sơ chế và làm sạch nguyên liệu thực vật tươi cho món Sinh tố bơ chuối cải kale giàu xơ.", "Bước 2: Nấu chín các nguyên liệu trên lửa vừa trong 20 phút, nêm gia vị thuần chay vừa ăn.", "Bước 3: Trình bày món Sinh tố bơ chuối cải kale giàu xơ ra đĩa hoặc tô, rắc ngò gai hoặc mè rang và thưởng thức nóng."]', 15, 20, 4, 240.0, 'MEDIUM', 1, 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252717/veggielife/recipes/sinh_to_bo_chuoi_kale.jpg', 'APPROVED_ACTIVE', 1475, 'USER', DATEADD(DAY, -13, SYSDATETIME())),
