        (145, 21, 145, N'Bún chả giò chay rau sống thanh mát', N'Bún tươi ăn kèm chả giò giòn tan, dưa leo băm, đồ chua và nước mắm chay chua ngọt thanh tao.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252700/veggielife/recipes/bun_cha_gio_chay.jpg', 'PUBLIC', 1130, 'APPROVED_ACTIVE', DATEADD(DAY, -22, SYSDATETIME()), NULL),
        (146, 22, 146, N'Hủ tiếu Nam Vang chay nước lèo mía lê', N'Nước súp trong ngọt thanh từ lê và mía lau, ăn kèm hủ tiếu dai và hoành thánh chiên.', 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1150, 'APPROVED_ACTIVE', DATEADD(DAY, -23, SYSDATETIME()), NULL),
        (147, 23, 147, N'Bánh canh nấm rơm giò chay đậm đà', N'Sợi bánh canh bột lọc dai dẻo chan nước dùng nấm sền sệt rắc tiêu đen thơm lừng.', 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1170, 'APPROVED_ACTIVE', DATEADD(DAY, -24, SYSDATETIME()), NULL),
        (148, 24, 148, N'Bún riêu chay cua đồng từ đậu hũ non', N'Riêu cua chay làm từ đậu hũ non xay nhuyễn và nấm rơm béo ngậy thơm mùi giấm bỗng.', 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1190, 'APPROVED_ACTIVE', DATEADD(DAY, -25, SYSDATETIME()), NULL),
        (149, 25, 149, N'Bún măng nấm chay nước dùng ngọt thanh', N'Măng tươi giòn ngọt nấu cùng nấm hương và nấm rơm tạo nên bát bún ấm áp bổ dưỡng.', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1210, 'APPROVED_ACTIVE', DATEADD(DAY, -26, SYSDATETIME()), NULL),
        (150, 26, 150, N'Cơm chiên trái thơm hạt sen', N'Cơm chiên hạt tơi xốp, ngọt dịu vị dứa tươi và bùi bùi từ hạt sen Đồng Tháp.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252695/veggielife/recipes/com_chien_trai_thom.jpg', 'PUBLIC', 1230, 'APPROVED_ACTIVE', DATEADD(DAY, -2, SYSDATETIME()), NULL),
        (151, 2, 151, N'Cơm niêu nấm rơm kho tộ cháy giòn', N'Cơm nấu niêu đất lớp cháy giòn rụm rưới nước sốt nấm rơm kho tộ thơm nức mũi.', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1250, 'APPROVED_ACTIVE', DATEADD(DAY, -3, SYSDATETIME()), NULL),
        (152, 3, 152, N'Cơm tấm sườn bì chả chay', N'Đĩa cơm tấm chuẩn vị Sài Gòn với sườn non chay ướp nướng, bì thính gạo và chả hấp.', 'https://images.unsplash.com/photo-1505253758473-96b301b5c81d?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1270, 'APPROVED_ACTIVE', DATEADD(DAY, -4, SYSDATETIME()), NULL),
        (153, 4, 153, N'Cơm cháy kho quẹt nấm rơm giòn rụm', N'Miếng cơm cháy chiên vàng giòn tan quệt đẫm nước kho quẹt nấm rơm đậm đà.', 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1290, 'APPROVED_ACTIVE', DATEADD(DAY, -5, SYSDATETIME()), NULL),
        (154, 5, 154, N'Cơm chiên ngọc bích rau bó xôi hạt sen', N'Màu xanh ngọc bích tự nhiên từ nước cốt cải bó xôi quyện cùng hạt sen bùi ngậy.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1310, 'APPROVED_ACTIVE', DATEADD(DAY, -6, SYSDATETIME()), NULL),
        (155, 6, 155, N'Cơm chiên kim chi đậu hũ cay ấm', N'Kim chi chay lên men chua cay xào cùng cơm trắng và đậu hũ cắt hạt lựu giòn thơm.', 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1330, 'APPROVED_ACTIVE', DATEADD(DAY, -7, SYSDATETIME()), NULL),
        (156, 7, 156, N'Cơm lam nấm nướng thơm lừng Tây Bắc', N'Gạo nếp nương nướng trong ống tre thơm mùi khói rừng ăn cùng muối vừng lạc rang.', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1350, 'APPROVED_ACTIVE', DATEADD(DAY, -8, SYSDATETIME()), NULL),
        (157, 8, 157, N'Cà ri chay khoai lang nước cốt dừa', N'Nước sốt cà ri vàng óng thơm ngậy mùi cốt dừa và khoai lang mật bùi béo ăn cùng bánh mì.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252694/veggielife/recipes/ca_ri_chay.jpg', 'PUBLIC', 1370, 'APPROVED_ACTIVE', DATEADD(DAY, -9, SYSDATETIME()), NULL),
        (158, 9, 158, N'Lẩu nấm thập cẩm thanh ngọt tự nhiên', N'Nồi lẩu ấm cúng quy tụ hơn 6 loại nấm quý, nước dùng trong vắt từ củ cải và bắp ngọt.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252765/veggielife/recipes/lau_nam_chay.jpg', 'PUBLIC', 1390, 'APPROVED_ACTIVE', DATEADD(DAY, -10, SYSDATETIME()), NULL),
        (159, 10, 159, N'Lẩu Thái chua cay chay nấm kim châm', N'Vị chua cay nồng nàn từ lá chanh Thái, sả ớt và nấm kim châm giòn ngọt ngào.', 'https://images.unsplash.com/photo-1567337710282-00832b415979?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1410, 'APPROVED_ACTIVE', DATEADD(DAY, -11, SYSDATETIME()), NULL),
        (160, 11, 160, N'Lẩu chao chay miền Tây khoai môn', N'Nước lẩu béo ngậy mùi chao trắng chao đỏ, khoai môn dẻo bùi và nấm rơm tươi.', 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1430, 'APPROVED_ACTIVE', DATEADD(DAY, -12, SYSDATETIME()), NULL),
        (161, 12, 161, N'Lẩu miso đậu hũ rong biển thanh tịnh', N'Hương vị lẩu dưỡng sinh Nhật Bản ngọt dịu từ tương miso lên men tự nhiên.', 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1450, 'APPROVED_ACTIVE', DATEADD(DAY, -13, SYSDATETIME()), NULL),
        (162, 13, 162, N'Lẩu nấm sa tế cay nồng ấm bụng', N'Nồi lẩu màu đỏ rực thơm lừng sa tế sả ớt xua tan cái lạnh ngày đông giá rét.', 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1470, 'APPROVED_ACTIVE', DATEADD(DAY, -14, SYSDATETIME()), NULL),
        (163, 14, 163, N'Lẩu kim chi đậu phụ nấm kim châm', N'Vị chua cay ấm nồng kiểu Hàn Quốc, ăn kèm mì sợi và nấm tươi giòn ngọt.', 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1490, 'APPROVED_ACTIVE', DATEADD(DAY, -15, SYSDATETIME()), NULL),
        (164, 15, 164, N'Cháo yến mạch nấm rơm hạt sen', N'Bát cháo sánh mịn giàu beta-glucan tốt cho tim mạch và dễ tiêu hóa cho bữa sáng.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252706/veggielife/recipes/chao_yen_mach_nam.jpg', 'PUBLIC', 1510, 'APPROVED_ACTIVE', DATEADD(DAY, -16, SYSDATETIME()), NULL),
        (165, 16, 165, N'Cháo đậu xanh hạt sen nấm đông cô', N'Đậu xanh nguyên vỏ nở mềm kết hợp hạt sen tươi thanh mát giải nhiệt độc cơ thể.', 'https://images.unsplash.com/photo-1498837167922-ddd27525d352?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1530, 'APPROVED_ACTIVE', DATEADD(DAY, -17, SYSDATETIME()), NULL),
        (166, 17, 166, N'Cháo nấm yến mạch củ sen thực dưỡng', N'Món cháo Ohsawa bồi bổ thể lực, củ sen giòn ngọt hòa cùng yến mạch sánh bùi.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1550, 'APPROVED_ACTIVE', DATEADD(DAY, -18, SYSDATETIME()), NULL),
        (167, 18, 167, N'Cháo nấm rơm cà rốt ngọt thanh', N'Cháo gạo tẻ ninh nhừ với nấm rơm búp tươi và cà rốt hạt lựu đỏ cam đẹp mắt.', 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1570, 'APPROVED_ACTIVE', DATEADD(DAY, -19, SYSDATETIME()), NULL),
        (168, 19, 168, N'Cháo bí đỏ đậu gà giàu đạm', N'Đậu gà bùi bùi giàu protein thực vật hầm nhừ cùng bí đỏ ngọt lịm bổ não.', 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1590, 'APPROVED_ACTIVE', DATEADD(DAY, -20, SYSDATETIME()), NULL),
        (169, 20, 169, N'Cháo gạo lứt đậu đen giải độc gan', N'Gạo lứt đỏ huyết rồng nấu cùng đậu đen xanh lòng thanh lọc gan thận tuyệt hảo.', 'https://images.unsplash.com/photo-1476718406336-bb5a9690ee2a?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1610, 'APPROVED_ACTIVE', DATEADD(DAY, -21, SYSDATETIME()), NULL),
        (170, 21, 170, N'Cháo nấm mối khoai môn dẻo thơm', N'Đặc sản nấm mối ngọt ngào tự nhiên ninh cùng khoai môn sáp dẻo quánh thơm lừng.', 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1630, 'APPROVED_ACTIVE', DATEADD(DAY, -22, SYSDATETIME()), NULL),
        (171, 22, 171, N'Bánh mì chay pate nấm chả lụa', N'Bánh mì giòn rụm phết pate nấm béo ngậy, kẹp chả lụa chay, dưa leo và ngò rí tươi.', 'https://res.cloudinary.com/swrsuenp/image/upload/v1792252710/veggielife/recipes/banh_mi_chay.jpg', 'PUBLIC', 1650, 'APPROVED_ACTIVE', DATEADD(DAY, -23, SYSDATETIME()), NULL),
        (172, 23, 172, N'Bánh ít trần chay nhân đậu xanh', N'Vỏ bánh nếp dẻo thơm nhân đậu xanh tán nhuyễn xào nấm mèo rắc hành boa rô phi.', 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 1670, 'APPROVED_ACTIVE', DATEADD(DAY, -24, SYSDATETIME()), NULL),
