        (190, 16, 190, N'Sinh tố thanh long đỏ dâu tây hạt chia', N'Màu hồng ngọc rực rỡ giàu chất chống oxy hóa anthocyanin và vitamin C tăng đề kháng.', 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', 'PUBLIC', 2030, 'APPROVED_ACTIVE', DATEADD(DAY, -17, SYSDATETIME()), NULL),
