USING (
    VALUES
        (7001, 501, 'USER', N'Chào VeggieBot, mình cao 1m60 nặng 54kg muốn ăn thuần chay để giảm xuống 50kg trong 1-2 tháng tới, bot có thể tư vấn giúp mình không?', NULL, DATEADD(DAY, -3, SYSDATETIME())),
        (7002, 501, 'ASSISTANT', N'Chào bạn! Với thể trạng hiện tại (BMI 21.1 bình thường), mức calo TDEE của bạn khoảng 1.720 kcal/ngày. Để giảm cân an toàn và bền vững, bạn nên thâm hụt khoảng 200-300 kcal, duy trì mức nạp vào từ 1.450 - 1.500 kcal/ngày. Ưu tiên các món giàu xơ và đạm thực vật như đậu hũ non, nấm rơm, súp ngô ngọt và các loại rau luộc. Khuyến nghị mang tính chất tham khảo dinh dưỡng, vui lòng tham vấn ý kiến bác sĩ chuyên khoa đối với các bệnh lý nền.', '{"tokensConsumed":450,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -3, SYSDATETIME())),
        (7003, 502, 'USER', N'Mình tập gym 4 buổi/tuần thì ăn chay có bị thiếu cơ không và nên nạp bao nhiêu protein mỗi ngày?', NULL, DATEADD(DAY, -1, SYSDATETIME())),
        (7004, 502, 'ASSISTANT', N'Chào bạn! Người ăn chay hoàn toàn có thể xây dựng cơ bắp săn chắc nếu nạp đủ từ 1.4 - 1.8g protein/kg thể trọng (tương đương 105 - 135g đạm/ngày với cân nặng 75kg). Bạn nên kết hợp đa dạng các nguồn đạm: yến mạch, đậu nành, hạt chia, diêm mạch quinoa và bơ đậu phộng để đảm bảo đủ 9 axit amin thiết yếu. Khuyến nghị mang tính chất tham khảo dinh dưỡng, vui lòng tham vấn ý kiến bác sĩ chuyên khoa đối với các bệnh lý nền.', '{"tokensConsumed":620,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -1, SYSDATETIME())),
        (7005, 503, 'USER', N'Bác sĩ bảo mình hơi thiếu sắt nhẹ, ăn chay nên ăn món gì để bổ sung sắt tốt nhất?', NULL, DATEADD(DAY, -3, SYSDATETIME())),
        (7006, 503, 'ASSISTANT', N'Chào bạn! Sắt thực vật (non-heme iron) có dồi dào trong rau bina, đậu lăng, mè đen, hạt bí và nấm mèo. Để tối ưu hấp thu sắt, hãy kết hợp ăn cùng thực phẩm giàu Vitamin C như ớt chuông, cà chua, nước chanh hoặc cam tươi. Tránh uống trà xanh hoặc cà phê ngay sau bữa ăn vì chất tannin làm giảm hấp thu sắt. Khuyến nghị mang tính chất tham khảo dinh dưỡng, vui lòng tham vấn ý kiến bác sĩ chuyên khoa đối với các bệnh lý nền.', '{"tokensConsumed":480,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -3, SYSDATETIME())),
        (7007, 504, 'USER', N'Mình theo đạo Phật kiêng Ngũ Vị Tân, có gia vị nào tạo hương thơm nồng thay thế hành tỏi không?', NULL, DATEADD(DAY, -3, SYSDATETIME())),
        (7008, 504, 'ASSISTANT', N'Chào bạn! Trong ẩm thực chay Phật giáo thanh tịnh, bạn hoàn toàn có thể sử dụng bột boa-rô (tùy tông phái), ngò rí, thì là, tiêu hồi, gừng tươi, quế, thảo quả và đặc biệt là bột thì là Ấn Độ (Cumin) hoặc bột ngải tây (Asafoetida - bột hưng cừ) để mang lại hương vị thơm nồng đậm đà mà 100% không phạm ngũ vị tân.', '{"tokensConsumed":410,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -3, SYSDATETIME())),
        (7009, 505, 'USER', N'VeggieBot gợi ý giúp mình một thực đơn 1 ngày đạt 130g protein từ thực vật thuần khiết nhé!', NULL, DATEADD(DAY, -2, SYSDATETIME())),
        (7010, 505, 'ASSISTANT', N'Gợi ý menu: Bữa sáng: Cháo yến mạch 80g + 30g bột đạm đậu nành + bơ đậu phộng (35g protein). Bữa trưa: 200g đậu hũ áp chảo + 100g đậu gà luộc + 1 chén quinoa (45g protein). Bữa xế: Sinh tố chuối hạt gai dầu & hạt chia (15g protein). Bữa tối: Cà ri tempeh nấm đùi gà 150g kèm súp lơ xanh (38g protein). Tổng protein: ~133g!', '{"tokensConsumed":530,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -2, SYSDATETIME())),
        (7011, 506, 'USER', N'Trước buổi tập yoga 90 phút buổi sáng thì ăn nhẹ gì để không bị nặng bụng?', NULL, DATEADD(DAY, -2, SYSDATETIME())),
        (7012, 506, 'ASSISTANT', N'Trước tập 45-60 phút, bạn chỉ nên ăn carbohydrate chuyển hóa nhanh và dễ tiêu hóa: 1 quả chuối chín kèm 1 thìa bơ hạt điều hoặc 2 quả chà là kèm vài hạt hạnh nhân. Uống 200ml nước ấm hoặc trà gừng mật ong để cơ thể mềm mại và tập trung.', '{"tokensConsumed":390,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -2, SYSDATETIME())),
        (7013, 507, 'USER', N'Nấu canh chua chay ngọt tự nhiên không cần đường cát thì dùng nguyên liệu gì?', NULL, DATEADD(DAY, -1, SYSDATETIME())),
        (7014, 507, 'ASSISTANT', N'Bạn hãy hầm nước dùng từ mía lau, củ cải trắng và bắp ngọt để lấy vị ngọt thanh nguyên bản. Vị chua lấy từ me tươi hoặc dứa (thơm) chín gọt lát. Dứa vừa tạo độ ngọt vừa tạo mùi thơm quyến rũ cho món canh chua chay!', '{"tokensConsumed":420,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -1, SYSDATETIME())),
        (7015, 508, 'USER', N'Tư vấn giúp em mâm cơm sinh viên 3 món chay ngân sách dưới 30k ở TP.HCM', NULL, DATEADD(DAY, -1, SYSDATETIME())),
        (7016, 508, 'ASSISTANT', N'Mâm cơm sinh viên 28k: 1. Đậu hũ sốt cà chua (2 miếng đậu 8k + 2 quả cà chua 5k = 13k). 2. Rau muống luộc chấm tương hột (1 bó rau muống 8k + tương 2k = 10k). 3. Nước rau muống dầm sấu/chanh làm canh (chanh 2k + ớt tỏi 3k = 5k). Vừa đủ chất xơ, đạm, vừa cực kỳ tiết kiệm!', '{"tokensConsumed":470,"modelVersion":"gemini-2.5-flash"}', DATEADD(DAY, -1, SYSDATETIME())),
        (7017, 509, 'USER', N'Detox thanh lọc gan bằng sinh tố rau củ 3 ngày có an toàn không bot?', NULL, DATEADD(HOUR, -12, SYSDATETIME())),
        (7018, 509, 'ASSISTANT', N'Thanh lọc cơ thể bằng nước ép cần tây, táo xanh, dưa chuột và gừng trong 1-3 ngày là an toàn đối với người khỏe mạnh. Tuy nhiên, không nên nhịn ăn hoàn toàn mà vẫn cần duy trì các bữa súp rau củ ấm để tránh tụt đường huyết. Khuyến nghị mang tính chất tham khảo dinh dưỡng, vui lòng tham vấn ý kiến bác sĩ chuyên khoa đối với các bệnh lý nền.', '{"tokensConsumed":460,"modelVersion":"gemini-2.5-flash"}', DATEADD(HOUR, -12, SYSDATETIME())),
        (7019, 510, 'USER', N'Người ăn chay trường phái Ovo ăn trứng gà công nghiệp có chứa phôi sống không?', NULL, DATEADD(HOUR, -8, SYSDATETIME())),
        (7020, 510, 'ASSISTANT', N'Trứng gà công nghiệp tại các siêu thị là trứng không thụ tinh (unfertilized eggs), không phát triển thành gà con sinh mạng. Do đó, người ăn chay theo trường phái Ovo-Vegetarian hoặc Lacto-Ovo hoàn toàn có thể yên tâm sử dụng để nạp protein và choline dồi dào.', '{"tokensConsumed":430,"modelVersion":"gemini-2.5-flash"}', DATEADD(HOUR, -8, SYSDATETIME())),
        (7021, 511, 'USER', N'Mình mới tập ăn chay mùng 1 và hôm rằm, chiều hay bị cồn cào đói thì làm sao?', NULL, DATEADD(HOUR, -4, SYSDATETIME())),
        (7022, 511, 'ASSISTANT', N'Hiện tượng đói nhanh là do bữa ăn có quá nhiều tinh bột tinh chế (cơm trắng) và thiếu chất béo tốt cùng protein no lâu. Hãy thay bằng cơm gạo lứt, thêm đậu phộng rang mè, đậu hũ chiên hoặc các loại nấm đùi gà xào. Chuẩn bị sẵn hạt óc chó hoặc sữa đậu nành không đường để uống lúc xế chiều nhé!', '{"tokensConsumed":450,"modelVersion":"gemini-2.5-flash"}', DATEADD(HOUR, -4, SYSDATETIME())),
        (7023, 512, 'USER', N'Làm sao để biết dầu hào nấm chay trong tiệm là thuần chay thật sự?', NULL, DATEADD(HOUR, -1, SYSDATETIME())),
        (7024, 512, 'ASSISTANT', N'Dầu hào chay thật sự được cô đặc từ nấm đông cô (nấm hương), nước tương lên men và tinh bột biến tính. Trên nhãn mác phải có logo Vegan hoặc chứng nhận không chứa chiết xuất hàu thịt (Oyster Extract E621/E635 có nguồn gốc động vật). Bạn có thể dùng tính năng quét mã Barcode của VeggieLife để kiểm tra ngay lập tức!', '{"tokensConsumed":490,"modelVersion":"gemini-2.5-flash"}', DATEADD(HOUR, -1, SYSDATETIME()))
) AS source (Message_ID, Chat_Session_ID, Sender_Type, Content, Metadata_JSON, Created_At)
ON target.Message_ID = source.Message_ID
WHEN MATCHED THEN
    UPDATE SET target.Content = source.Content
WHEN NOT MATCHED THEN
